import{_ as e,o,c as d,a3 as a}from"./chunks/framework.cNy3aYYk.js";const m=JSON.parse('{"title":"Tenant API v1 — Customer Portal","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Customer Portal | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-customer-portal"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Customer Portal | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-customer-portal"}]]},"headers":[],"relativePath":"api/tenant-v1-customer-portal.md","filePath":"api/tenant-v1-customer-portal.md","lastUpdated":1791478559000}'),c={name:"api/tenant-v1-customer-portal.md"};function r(n,t,s,l,i,p){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="tenant-api-v1-—-customer-portal" tabindex="-1">Tenant API v1 — Customer Portal <a class="header-anchor" href="#tenant-api-v1-—-customer-portal" aria-label="Permalink to &quot;Tenant API v1 — Customer Portal&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><h2 id="staff-routes" tabindex="-1">Staff routes <a class="header-anchor" href="#staff-routes" aria-label="Permalink to &quot;Staff routes&quot;">​</a></h2><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:customer-portal</code>, plus <code>can:customer-portal.*</code>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/customer-portal/users</code></td><td><code>view</code></td></tr><tr><td>POST</td><td><code>/customer-portal/contacts/{contact}/invite</code></td><td><code>invite</code></td></tr><tr><td>POST</td><td><code>/customer-portal/users/{portalUser}/resend</code></td><td><code>invite</code></td></tr><tr><td>POST</td><td><code>/customer-portal/users/{portalUser}/disable</code></td><td><code>manage</code></td></tr><tr><td>POST</td><td><code>/customer-portal/users/{portalUser}/enable</code></td><td><code>manage</code></td></tr></tbody></table><p>Invite requires the Contact to have a non-empty email. Creates or rotates an invite token and emails <code>FrontendUrl::portalInvite()</code>.</p><h2 id="portal-auth-no-staff-token" tabindex="-1">Portal auth (no staff token) <a class="header-anchor" href="#portal-auth-no-staff-token" aria-label="Permalink to &quot;Portal auth (no staff token)&quot;">​</a></h2><p>Tenancy via domain / <code>X-Tenant-Domain</code>. Prefix <code>/portal/auth</code>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td>POST</td><td><code>/portal/auth/accept-invite</code></td><td><code>{ token, password, password_confirmation }</code> → active + bearer</td></tr><tr><td>POST</td><td><code>/portal/auth/login</code></td><td><code>{ email, password }</code> — status must be <code>active</code>; may return <code>two_factor_required</code> + <code>challenge_token</code></td></tr><tr><td>POST</td><td><code>/portal/auth/magic-link</code></td><td><code>{ email }</code> — always generic success; emails Active accounts only (Central mail)</td></tr><tr><td>POST</td><td><code>/portal/auth/magic-link/consume</code></td><td><code>{ token }</code> → bearer or 2FA challenge</td></tr><tr><td>POST</td><td><code>/portal/auth/two-factor-challenge</code></td><td><code>{ challenge_token, code }</code> → bearer</td></tr><tr><td>GET/POST/DELETE</td><td><code>/portal/auth/two-factor</code> (+ <code>confirm</code>, <code>recovery-codes</code>)</td><td><code>auth:portal-api</code> — Fortify TOTP manage</td></tr><tr><td>POST</td><td><code>/portal/auth/forgot-password</code></td><td><code>{ email }</code></td></tr><tr><td>POST</td><td><code>/portal/auth/reset-password</code></td><td><code>{ token, email, password, password_confirmation }</code></td></tr><tr><td>POST</td><td><code>/portal/auth/logout</code></td><td><code>auth:portal-api</code></td></tr><tr><td>GET</td><td><code>/portal/auth/me</code></td><td><code>auth:portal-api</code></td></tr></tbody></table><p>Throttled (login / magic consume / 2FA challenge use <code>auth-login</code>; invite/reset/magic-link request <code>6,1</code>). No open registration endpoint.</p><h2 id="shared-host-workspace-lookup-central" tabindex="-1">Shared-host workspace lookup (central) <a class="header-anchor" href="#shared-host-workspace-lookup-central" aria-label="Permalink to &quot;Shared-host workspace lookup (central)&quot;">​</a></h2><p>Unauthenticated. Not a tenant directory — returns only workspaces where this email already has an invited or active portal account.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th></tr></thead><tbody><tr><td>POST</td><td><code>/api/central/v1/public/portal-workspaces</code> <code>{ email }</code> → <code>{ workspaces: [{ name, domain, slug }] }</code></td></tr></tbody></table><p>Throttle: <code>portal-workspace-lookup</code> (8/min per IP+email). Disabled accounts and unavailable tenants are omitted. Unknown email returns an empty list (200).</p><h2 id="portal-data" tabindex="-1">Portal data <a class="header-anchor" href="#portal-data" aria-label="Permalink to &quot;Portal data&quot;">​</a></h2><p>Middleware: <code>auth:portal-api</code>, <code>module:customer-portal</code>. Soft module checked per resource (403 if missing). Scope via <code>PortalRecordScope</code> — out of scope → <strong>404</strong>.</p><table tabindex="0"><thead><tr><th>Area</th><th>Paths</th><th>Soft module</th></tr></thead><tbody><tr><td>Invoices</td><td><code>GET /portal/invoices</code>, <code>/{id}</code>, <code>/{id}/pdf</code></td><td><code>invoices</code></td></tr><tr><td>Payments</td><td><code>GET /portal/payments</code>, <code>/{id}</code>, <code>/{id}/pdf</code></td><td><code>payments</code></td></tr><tr><td>Quotations</td><td><code>GET …</code>, <code>/{id}</code>, <code>/{id}/pdf</code>, <code>POST …/acceptance-link</code></td><td><code>quotations</code></td></tr><tr><td>Contracts</td><td>same as quotations</td><td><code>contracts</code></td></tr><tr><td>Help Desk</td><td><code>GET/POST /portal/help-desk</code>, <code>GET /{id}</code>, <code>POST /{id}/notes</code>, <code>GET /note-attachments/{uuid}/download</code></td><td><code>help-desk</code></td></tr><tr><td>Knowledge Base</td><td><code>GET /portal/knowledge-base</code>, <code>GET /{id}</code></td><td><code>knowledge-base</code></td></tr><tr><td>Projects</td><td><code>GET /portal/projects</code>, <code>/{id}</code>, <code>/{id}/tasks</code>, <code>/{id}/timeline</code></td><td><code>projects</code> (+ <code>tasks</code> for nested tasks)</td></tr></tbody></table><p>Create ticket body: <code>subject</code> (required), <code>description</code> optional (HTML, max 10000). Server stamps <code>contact_id</code> / <code>company_id</code> from the portal user’s Contact — client-supplied party IDs are ignored.</p><p>Help Desk show embeds <strong>public</strong> notes only (<code>is_internal = false</code>), oldest-first conversation order, with optional attachments. <code>POST /{id}/notes</code> accepts JSON or multipart (<code>body</code> max 10000, optional <code>attachment</code>). Portal replies are always public and do not set SLA first response. A public customer reply (portal or email ingest) on a <strong>closed</strong> or <strong>resolved</strong> ticket reopens it to <strong>open</strong>. <code>GET /portal/help-desk/note-attachments/{uuid}/download</code> streams a public-note attachment in scope (404 for internal attachments or out-of-scope tickets).</p><p>Knowledge Base lists/shows <strong>published</strong> articles only.</p><p>Projects require <code>portal_visible</code> plus Contact/Company scope. Nested tasks require <code>visible_to_portal</code>. Timeline is filtered to customer-safe activity types.</p>',21)])])}const u=e(c,[["render",r]]);export{m as __pageData,u as default};
